#include <cuda_runtime.h>
#include <chrono>
#include "study_support.h"
#include "../b+tree-cuda/common.h"
#undef malloc
#include "../b+tree-cuda/kernel/kernel.cu"
#include "../b+tree-cuda/kernel/kernel2.cu"
#define CK(x)do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}while(0)
template<class T>struct B{std::vector<T>host;T*raw;T*data;B(const std::vector<T>&v):host(v){CK(cudaMalloc(&raw,(v.size()+128)*sizeof(T)));data=raw+64;}void reset(){std::vector<T>v(host.size()+128,T(-777));std::copy(host.begin(),host.end(),v.begin()+64);CK(cudaMemcpy(raw,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>read(){std::vector<T>v(host.size());CK(cudaMemcpy(v.data(),data,v.size()*sizeof(T),cudaMemcpyDeviceToHost));return v;}void guards(std::vector<int64_t>&o){std::vector<T>v(host.size()+128);CK(cudaMemcpy(v.data(),raw,v.size()*sizeof(T),cudaMemcpyDeviceToHost));for(int j=0;j<64;j++)o.push_back(v[j]);for(size_t j=v.size()-64;j<v.size();j++)o.push_back(v[j]);}void readonly(){auto v=read();if(memcmp(v.data(),host.data(),v.size()*sizeof(T)))throw std::runtime_error("readonly");}};
struct GC{Case c;B<int32_t>nodes,records,keys,start,end,ans,rs,rl;B<int64_t>pc,po,rc,ro,last,off2;GC(Case x):c(x),nodes(x.nodes),records(x.records),keys(x.keys),start(x.start),end(x.end),ans(std::vector<int32_t>(x.q,-777)),rs(std::vector<int32_t>(x.q,-777)),rl(std::vector<int32_t>(x.q,-777)),pc(std::vector<int64_t>(x.q,0)),po(std::vector<int64_t>(x.q,0)),rc(std::vector<int64_t>(x.q,0)),ro(std::vector<int64_t>(x.q,0)),last(std::vector<int64_t>(x.q,0)),off2(std::vector<int64_t>(x.q,0)){}void reset(){for(auto*b:{&nodes,&records,&keys,&start,&end,&ans,&rs,&rl})b->reset();for(auto*b:{&pc,&po,&rc,&ro,&last,&off2})b->reset();}void point(){findK<<<c.q,256>>>(c.h,(knode*)nodes.data,c.nn,(record*)records.data,pc.data,po.data,keys.data,(record*)ans.data);CK(cudaGetLastError());}void range(){findRangeK<<<c.q,256>>>(c.h,(knode*)nodes.data,c.nn,rc.data,ro.data,last.data,off2.data,start.data,end.data,rs.data,rl.data);CK(cudaGetLastError());}};
int main(){try{auto inputs=cases();std::vector<GC*>cs;for(auto&c:inputs){topology(c);auto*g=new GC(c);g->reset();g->point();g->range();CK(cudaDeviceSynchronize());cs.push_back(g);}for(int trial=1;trial<=5;trial++){std::vector<int64_t>out{3};auto arr=[&](const auto&v){for(auto x:v)out.push_back(x);};for(auto*g:cs){g->reset();for(int h:{g->c.n,g->c.nn,g->c.h,g->c.q})out.push_back(h);for(auto*b:{&g->nodes,&g->records,&g->keys,&g->start,&g->end})arr(b->read());arr(g->pc.read());arr(g->po.read());arr(g->ans.read());for(auto*b:{&g->rc,&g->ro,&g->last,&g->off2})arr(b->read());arr(g->rs.read());arr(g->rl.read());}double sec=0;for(auto*g:cs){CK(cudaDeviceSynchronize());auto begin=std::chrono::steady_clock::now();g->point();CK(cudaDeviceSynchronize());sec+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();begin=std::chrono::steady_clock::now();g->range();CK(cudaDeviceSynchronize());sec+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();arr(g->pc.read());arr(g->po.read());arr(g->ans.read());for(auto*b:{&g->rc,&g->ro,&g->last,&g->off2})arr(b->read());arr(g->rs.read());arr(g->rl.read());for(auto*b:{&g->nodes,&g->records,&g->keys,&g->start,&g->end})b->readonly();for(auto*b:{&g->nodes,&g->records,&g->keys,&g->start,&g->end,&g->ans,&g->rs,&g->rl})b->guards(out);for(auto*b:{&g->pc,&g->po,&g->rc,&g->ro,&g->last,&g->off2})b->guards(out);}std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();double met[2];if(study_check(path.c_str(),met))return 1;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum3_point_and_range_kernel_context_complete\",\"jit_excluded\":true,\"internal_repeats\":6,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,sec,out.size(),path.c_str(),out.size());}for(auto*g:cs){for(auto*b:{&g->nodes,&g->records,&g->keys,&g->start,&g->end,&g->ans,&g->rs,&g->rl})cudaFree(b->raw);for(auto*b:{&g->pc,&g->po,&g->rc,&g->ro,&g->last,&g->off2})cudaFree(b->raw);delete g;}return 0;}catch(std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
